module ActionController
module AllowBrowser;extend ActiveSupport::Concern;module ClassMethods;def allow_browser(versions:,block:->{render file:Rails.root.join("public/406-unsupported-browser.html"),layout:false,status: :not_acceptable},**options)before_action->{allow_browser(versions:versions,block:block)},**options;end;end;private;def allow_browser(versions:,block:)require"useragent";if BrowserBlocker.new(request,versions:versions).blocked?;ActiveSupport::Notifications.instrument("browser_block.action_controller",request:request,versions:versions) do block.is_a?(Symbol) ? send(block): instance_exec(&block);end;end;end;class BrowserBlocker
SETS={modern:{safari:17.2,chrome:120,firefox:121,opera:106,ie:false}};attr_reader:request,:versions;def initialize(request,versions:)@request,@versions=request,versions;end;def blocked?;user_agent_version_reported?&&unsupported_browser?;end;private;def parsed_user_agent;@parsed_user_agent||=UserAgent.parse(request.user_agent);end;def user_agent_version_reported?;request.user_agent.present?&&parsed_user_agent.version.to_s.present?;end;def unsupported_browser?;version_guarded_browser?&&version_below_minimum_required?&&!bot?;end;def version_guarded_browser?;minimum_browser_version_for_browser!=nil;end;def bot?;parsed_user_agent.bot?;end;def version_below_minimum_required?;if minimum_browser_version_for_browser;parsed_user_agent.version<UserAgent::Version.new(minimum_browser_version_for_browser.to_s);else true;end;end;def minimum_browser_version_for_browser;expanded_versions[normalized_browser_name];end;def expanded_versions;@expanded_versions||=(SETS[versions]||versions).with_indifferent_access;end;def normalized_browser_name;case name=parsed_user_agent.browser.downcase;when "internet explorer" then "ie";else name;end;end;end;end;end
